with(obj_unit)
{
if sk_in_view(x, y) and sk_in_fog(sys_fog, x, y, 0)
{

sk_udraw_color(player)
draw_ellipse(x+3,bbox_top-15,x-5,bbox_top-10,0)
draw_set_color(c_black)
//플레이어 구별

if click_check=1
{
draw_set_color(c_red)
sk_draw_gauge_bar(hp, max_hp, x-15, bbox_top-1, x+15, bbox_top-6, 0)
